import sys
import numpy as np
from scipy.sparse import csr_matrix, csc_matrix
from sklearn.utils.sparsefuncs import incr_mean_variance_axis, csr_row_norms
failed = 0

def check(ok: bool, msg: str):
    global failed
    if not ok:
        print("FAIL", msg)
        failed += 1

def close(got, exp: List[float], rtol: float = 1e-10, atol: float = 1e-12) -> bool:
    g = np.asarray(got, dtype=float).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    for i in range(len(exp)):
        if abs(g[i] - exp[i]) > atol + rtol * abs(exp[i]):
            print("mismatch at", i, g[i], exp[i])
            return False
    return True

n = 12
A = np.zeros((n, 4))
for i in range(n):
    for j in range(4):
        v = (i * 7919 + j * 104729 + i * j * 13) % 7
        A[i, j] = float(v) if v > 2 else 0.0
S1 = csr_matrix(A[:5])
S2 = csr_matrix(A[5:])
S3 = csc_matrix(A[5:])

